style.css:
@-moz-document domain("music.youtube.com") {
/* Body & Background */
    body, ytmusic-app {
        background-color: #0d0d1a !important;
        color: #f0f0f0 !important;
        font-family: 'Orbitron', sans-serif !important;
    }

    /* Navigation Bar & Player Bar */
    ytmusic-nav-bar, ytmusic-player-bar {
        background-color: #0d0d1a !important;
        border-top: 2px solid #00ffff !important;
    }

    /* Links & Text */
    a, .title, .yt-simple-endpoint {
        color: #00ffff !important;
    }

    /* Video/Section Backgrounds */
    ytmusic-shelf-renderer, ytmusic-section-list-renderer {
        background-color: #111129 !important;
        border-radius: 12px !important;
        padding: 6px !important;
        margin: 4px 0 !important;
    }

    /* Player Glow */
    ytmusic-player-bar {
        box-shadow: 0 0 20px #00ffff !important;
    }

    /* Buttons */
    button, paper-icon-button, ytmusic-toggle-button-renderer {
        background-color: #0d0d1a !important;
        color: #00ffff !important;
        border: 1px solid #00ffff !important;
        border-radius: 4px !important;
    }

    /* Hover Effects */
    ytmusic-player-bar button:hover,
    ytmusic-shelf-renderer:hover {
        box-shadow: 0 0 15px #ff00ff !important;
        border-color: #ff00ff !important;
    }
}
